exercise.solution:
def creer_message(role, contenu):
    if role not in {'system','user','assistant','tool'} or not isinstance(contenu,str):
        raise ValueError('message invalide')
    return {'role':role,'content':contenu}

exercise.check:
assert creer_message('user','salut')=={'role':'user','content':'salut'}
assert creer_message('tool','donnée')['role']=='tool'
for role,contenu in [('root','x'),('user',7)]:
    try: creer_message(role,contenu)
    except ValueError: pass
    else: raise AssertionError('message invalide accepté')
